package com.example.valtiva.data.local.entity

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * A currency the app knows how to display.
 *
 * The ISO 4217 code is the natural identity of a currency, so it *is* the primary key. An
 * autogenerated id would add a second identity with no benefit and would let the same code be
 * inserted twice.
 *
 * Kept so the UI can show "US Dollar" and "$" instead of a bare code while offline; the rate tables
 * only ever store codes.
 */
@Entity(tableName = "currencies")
data class CurrencyEntity(
  @PrimaryKey
  @ColumnInfo(name = "code") val code: String,
  @ColumnInfo(name = "name") val name: String,
  @ColumnInfo(name = "symbol") val symbol: String?,
)
